<script setup>
import { ref, reactive, onMounted } from 'vue'
import { ArrowLeft, Check, Lock, Key, Message, Phone, OfficeBuilding } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import api from '@/api'
import { useRouter } from 'vue-router'

const router = useRouter()
const activeTab = ref('profile')
const currentUser = ref(null)
const saving = ref(false)
const passwordSaving = ref(false)

const form = reactive({
  name: '',
  email: '',
  phone: '',
  student_id: ''
})

const passwordForm = reactive({
  old_password: '',
  new_password: '',
  confirm_password: ''
})

const passwordFormRef = ref(null)

const passwordRules = {
  old_password: [{ required: true, message: '请输入当前密码', trigger: 'blur' }],
  new_password: [
    { required: true, message: '请输入新密码', trigger: 'blur' },
    { min: 6, message: '密码长度至少6位', trigger: 'blur' }
  ],
  confirm_password: [
    { required: true, message: '请确认新密码', trigger: 'blur' },
    {
      validator: (rule, value, callback) => {
        if (value !== passwordForm.new_password) {
          callback(new Error('两次输入密码不一致'))
        } else {
          callback()
        }
      },
      trigger: 'blur'
    }
  ]
}

const getRoleType = (role) => {
  const map = {
    '管理员': 'danger',
    '教师': 'warning',
    '导师': 'warning',
    '硕士生': 'success',
    '博士生': 'primary'
  }
  return map[role] || 'info'
}

const resetForm = () => {
  if (currentUser.value) {
    form.name = currentUser.value.name
    form.email = currentUser.value.email
    form.phone = currentUser.value.phone
    form.student_id = currentUser.value.student_id
  }
}

onMounted(() => {
  const userStr = localStorage.getItem('user')
  if (userStr) {
    currentUser.value = JSON.parse(userStr)
    form.name = currentUser.value.name
    form.email = currentUser.value.email
    form.phone = currentUser.value.phone
    form.student_id = currentUser.value.student_id
  }
})

const handleUpdate = async () => {
  if (!form.name) {
    ElMessage.warning('姓名不能为空')
    return
  }

  saving.value = true
  try {
    const payload = {
      name: form.name,
      email: form.email || '',
      phone: form.phone || ''
    }
    await api.updateProfile(currentUser.value.id, payload)
    
    // 更新本地缓存
    const updatedUser = { ...currentUser.value, ...payload }
    localStorage.setItem('user', JSON.stringify(updatedUser))
    currentUser.value = updatedUser
    
    ElMessage.success('个人资料更新成功')
  } catch (error) {
    ElMessage.error(error.response?.data?.error || '更新失败')
  } finally {
    saving.value = false
  }
}

const handleChangePassword = async () => {
  if (!passwordFormRef.value) return
  
  try {
    await passwordFormRef.value.validate()
  } catch {
    return
  }

  passwordSaving.value = true
  try {
    await api.changePassword(passwordForm.old_password, passwordForm.new_password, currentUser.value.user_id)
    ElMessage.success('密码修改成功，请重新登录')
    setTimeout(() => {
      localStorage.removeItem('access_token')
      localStorage.removeItem('refresh_token')
      localStorage.removeItem('user')
      router.push('/login')
    }, 1500)
  } catch (error) {
    ElMessage.error(error.response?.data?.error || '密码修改失败')
  } finally {
    passwordSaving.value = false
  }
}
</script>

